"""Build the browser adapter from the existing platform-neutral AE shuffle engine."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def build():
    source = (ROOT / "ae/lib/style_shuffle.jsx").read_text(encoding="utf-8").rstrip()
    adapter = (
        "/* Generated by scripts/sync_preview_styles.py. Edit ae/lib/style_shuffle.jsx. */\n"
        "(function (root) {\n\"use strict\";\n" + source + "\n"
        "var api = {create: KCF_shufflerFor, variant: KCF_variantStyle};\n"
        "if (typeof module !== 'undefined' && module.exports) { module.exports = api; }\n"
        "else { root.KCF_WordStyles = api; }\n}(typeof window !== 'undefined' ? window : this));\n"
    )
    (ROOT / "panel/js/word_styles.js").write_text(adapter, encoding="utf-8")


if __name__ == "__main__":
    build()
